import { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import axios from "axios";

function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const login = async () => {
    if (!email || !password) {
      setError("Please enter email and password");
      return;
    }
    
    setLoading(true);
    setError("");
    
    try {
      const res = await axios.post("http://127.0.0.1:5000/login", {
        email,
        password
      });
      
      if (res.data.success) {
        localStorage.setItem("user", JSON.stringify(res.data.user));
        navigate("/health");
      } else {
        setError(res.data.message);
      }
    } catch (err) {
      setError(err.response?.data?.message || "Login failed. Please try again.");
    }
    setLoading(false);
  };

  return (
    <div style={{
      minHeight: "100vh",
      background: "#f8f9fa",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      fontFamily: "Arial, sans-serif"
    }}>
      <div style={{
        background: "white",
        padding: "40px",
        borderRadius: "15px",
        boxShadow: "0 10px 40px rgba(0,0,0,0.2)",
        width: "100%",
        maxWidth: "400px"
      }}>
        <h2 style={{textAlign: "center", color: "#333", marginBottom: "30px"}}>
          🔐 Login
        </h2>
        
        {error && (
          <div style={{
            background: "#ffebee",
            color: "#c62828",
            padding: "10px",
            borderRadius: "5px",
            marginBottom: "20px",
            textAlign: "center"
          }}>
            {error}
          </div>
        )}
        
        <div style={{marginBottom: "20px"}}>
          <label style={{display: "block", marginBottom: "5px", color: "#555"}}>Email</label>
          <input 
            type="email"
            placeholder="Enter your email" 
            value={email}
            onChange={e => setEmail(e.target.value)}
            style={{
              width: "100%",
              padding: "12px",
              border: "1px solid #ddd",
              borderRadius: "8px",
              fontSize: "16px",
              boxSizing: "border-box"
            }}
          />
        </div>
        
        <div style={{marginBottom: "25px"}}>
          <label style={{display: "block", marginBottom: "5px", color: "#555"}}>Password</label>
          <input 
            type="password" 
            placeholder="Enter your password" 
            value={password}
            onChange={e => setPassword(e.target.value)}
            style={{
              width: "100%",
              padding: "12px",
              border: "1px solid #ddd",
              borderRadius: "8px",
              fontSize: "16px",
              boxSizing: "border-box"
            }}
          />
        </div>
        
        <button 
          onClick={login}
          disabled={loading}
          style={{
            width: "100%",
            padding: "14px",
            background: "#4CAF50",
            color: "white",
            border: "none",
            borderRadius: "8px",
            fontSize: "16px",
            fontWeight: "bold",
            cursor: loading ? "not-allowed" : "pointer",
            opacity: loading ? 0.7 : 1
          }}
        >
          {loading ? "Logging in..." : "Login"}
        </button>
        
        <p style={{textAlign: "center", marginTop: "20px", color: "#666"}}>
          Don't have an account? <Link to="/signup" style={{color: "#4CAF50", textDecoration: "none", fontWeight: "bold"}}>Sign Up</Link>
        </p>
        
        <p style={{textAlign: "center", marginTop: "10px"}}>
          <Link to="/" style={{color: "#999", textDecoration: "none", fontSize: "14px"}}>← Back to Home</Link>
        </p>
      </div>
    </div>
  );
}

export default Login;
